            <span>🏢 Chủ quản: <strong className="text-gray-600">{item.chuQuan}</strong></span>
          )}
          {item.namTrienKhai && (
            <span>📅 Triển khai: <strong className="text-gray-600">{item.namTrienKhai}</strong></span>
          )}
          {item.donVi && (
            <span>📍 Đơn vị: <strong className="text-gray-600">{item.donVi.ten}</strong></span>
          )}
        </div>
      </Card>
    );
  };

  const LopTab = ({ lop }: { lop: 1 | 2 | 3 | 4 }) => {
    const items = byLop(lop);
    const cfg = LOP_CONFIG[lop];
    const dangVanHanh = items.filter((i) => i.trangThai === "dang-van-hanh").length;
    const canNangCap = items.filter((i) => i.trangThai === "can-nang-cap").length;
    const canThayThe = items.filter((i) => i.trangThai === "can-thay-the").length;

    return (
      <div>
        {/* Summary */}
        <div
          className="p-4 rounded-xl mb-4 border"
          style={{ backgroundColor: cfg.bgColor, borderColor: cfg.borderColor }}
        >
          <div className="flex items-center gap-3 mb-3">
            <span className="text-2xl">{cfg.icon}</span>
            <div>
              <div className="font-bold" style={{ color: cfg.color }}>{cfg.label}</div>
              <div className="text-gray-500 text-sm">Tổng cộng: {items.length} hệ thống/thành phần</div>
            </div>
          </div>
          <div className="flex gap-4">
            <Badge color="green" text={<span className="text-sm">Đang vận hành: {dangVanHanh}</span>} />
            <Badge color="orange" text={<span className="text-sm">Cần nâng cấp: {canNangCap}</span>} />
            <Badge color="red" text={<span className="text-sm">Cần thay thế: {canThayThe}</span>} />
          </div>
        </div>

        {/* Items */}
        {items.length === 0 ? (
          <Empty description="Chưa có hệ thống nào trong lớp này" />
        ) : (
          items.map((item) => <HeThongCard key={item.id} item={item} />)
        )}
      </div>
    );
  };

  const tabItems = ([1, 2, 3, 4] as const).map((lop) => {
    const cfg = LOP_CONFIG[lop];
    const count = byLop(lop).length;
    return {
      key: String(lop),
      label: (
        <span className="flex items-center gap-2">
          <span>{cfg.icon}</span>
          <span>{cfg.shortLabel}</span>
          <Badge count={count} style={{ backgroundColor: cfg.color }} />
        </span>
      ),
      children: <LopTab lop={lop} />,
    };
  });

  if (loading) {
    return (
      <div className="flex justify-center py-20">
        <Spin size="large" tip="Đang tải dữ liệu..." />
      </div>
    );
  }

  return (
    <div>
      <div className="page-header mb-6">
        <h1 className="text-2xl font-bold">Đánh giá Hiện trạng Kiến trúc Số</h1>
        <p className="text-blue-200 mt-1">
          Kiểm kê và đánh giá các thành phần số hiện có theo 4 lớp kiến trúc
        </p>
      </div>

      {/* Tổng quan nhanh */}
      <div className="grid grid-cols-4 gap-4 mb-6">
        {([1, 2, 3, 4] as const).map((lop) => {
          const cfg = LOP_CONFIG[lop];
          const items = byLop(lop);
          const pct =
            items.length > 0
              ? Math.round(
                  (items.filter((i) => i.trangThai === "dang-van-hanh").length /
                    items.length) *
                    100
                )
              : 0;
          return (
            <Card
              key={lop}
              size="small"
              className="text-center cursor-pointer hover:shadow-md transition-shadow"
              onClick={() => setActiveTab(String(lop))}
              style={{ borderColor: cfg.borderColor, backgroundColor: cfg.bgColor }}
            >
              <div className="text-2xl mb-1">{cfg.icon}</div>
              <div className="text-xs font-medium mb-2" style={{ color: cfg.color }}>
                {cfg.shortLabel}
              </div>
              <Tooltip title={`${items.filter(i => i.trangThai === 'dang-van-hanh').length}/${items.length} đang vận hành tốt`}>
                <Progress
                  percent={pct}
                  size="small"
                  strokeColor={cfg.color}
                  format={(p) => `${p}%`}
                />
              </Tooltip>
            </Card>
          );
        })}
      </div>

      <Card className="shadow-sm">
        <Tabs
          activeKey={activeTab}
          onChange={setActiveTab}
          items={tabItems}
          size="large"
        />
      </Card>
    </div>
  );
}

"use client";
import ReactFlow, {
  Background,
  Controls,
  Node,
  Edge,
  MarkerType,
  NodeTypes,
} from "reactflow";
import "reactflow/dist/style.css";
import { Card, Tag } from "antd";
import { LOP_CONFIG } from "@/lib/utils";

const CustomNode = ({ data }: { data: { label: string; sub?: string; color: string; bgColor: string; icon: string } }) => (
  <div
    className="px-4 py-3 rounded-xl border-2 min-w-[180px] max-w-[220px] text-center shadow-sm"
    style={{ borderColor: data.color, backgroundColor: data.bgColor }}
  >
    <div className="text-lg mb-1">{data.icon}</div>
    <div className="font-semibold text-sm" style={{ color: data.color }}>{data.label}</div>
    {data.sub && <div className="text-xs text-gray-500 mt-1">{data.sub}</div>}
  </div>
);

const GroupNode = ({ data }: { data: { label: string; color: string; bgColor: string } }) => (
  <div
    className="rounded-2xl border-2 border-dashed px-3 py-2"
    style={{ borderColor: data.color, backgroundColor: data.bgColor + "60" }}
  >
    <div className="font-bold text-sm" style={{ color: data.color }}>{data.label}</div>
  </div>
);

const nodeTypes: NodeTypes = {
  custom: CustomNode,
  group: GroupNode,
};

function buildNodes(): Node[] {
  const nodes: Node[] = [];
  const layers = [
    {
      lop: 4,
      label: "LỚP 4 — KÊNH TƯƠNG TÁC & ĐO LƯỜNG",
      y: 0,
      items: [
        { id: "kt-web", label: "Cổng thông tin điện tử", icon: "🌐" },
        { id: "kt-dvctt", label: "Cổng DVCTT tỉnh", icon: "📋" },
        { id: "kt-app", label: "App Vĩnh Long Smart", icon: "📱", planned: true },
        { id: "kt-kpi", label: "Đo lường KPI/KPD", icon: "📊" },
      ],
    },
    {
      lop: 3,
      label: "LỚP 3 — ỨNG DỤNG & NGHIỆP VỤ",
      y: 180,
      items: [
        { id: "ud-qlvb", label: "Quản lý Văn bản", icon: "📄" },
        { id: "ud-his", label: "HIS Y tế", icon: "🏥" },
        { id: "ud-gd", label: "Hệ thống GD&ĐT", icon: "🎓" },
        { id: "ud-ai", label: "Trợ lý ảo tỉnh", icon: "🤖", planned: true },
      ],
    },
    {
      lop: 2,
      label: "LỚP 2 — DỮ LIỆU & NỀN TẢNG LÕI",
      y: 360,
      items: [
        { id: "dl-dancu", label: "CSDL Dân cư", icon: "👥" },
        { id: "dl-datdai", label: "CSDL Đất đai", icon: "🗺️" },
        { id: "dl-lgsp", label: "LGSP (Tích hợp & chia sẻ)", icon: "🔗" },
        { id: "dl-tddl", label: "Từ điển dữ liệu", icon: "📚", planned: true },
      ],
    },
    {
      lop: 1,
      label: "LỚP 1 — HẠ TẦNG SỐ & AN NINH MẠNG",
      y: 540,
      items: [
        { id: "ht-wan", label: "Mạng WAN tỉnh", icon: "🕸️" },
        { id: "ht-idc", label: "IDC / Cloud tỉnh", icon: "☁️" },
        { id: "ht-soc", label: "SOC An ninh mạng", icon: "🛡️" },
        { id: "ht-vpn", label: "VPN & Bảo mật", icon: "🔐" },
      ],
    },
  ];

  layers.forEach((layer) => {
    const cfg = LOP_CONFIG[layer.lop as 1 | 2 | 3 | 4];
    // Group node
    nodes.push({
      id: `group-${layer.lop}`,
      type: "group",
      position: { x: 20, y: layer.y },
      style: { width: 900, height: 140 },
      data: { label: layer.label, color: cfg.color, bgColor: cfg.bgColor },
      draggable: false,
    });

    layer.items.forEach((item, idx) => {
      nodes.push({
        id: item.id,
        type: "custom",
        position: { x: 60 + idx * 210, y: layer.y + 45 },
        data: {
          label: item.label,
          icon: item.icon,
          color: cfg.color,
          bgColor: item.planned ? "#f5f5f5" : cfg.bgColor,
          sub: item.planned ? "Kế hoạch" : undefined,
        },
        parentId: `group-${layer.lop}`,
        extent: "parent" as const,
      });
    });
  });

  return nodes;
}

function buildEdges(): Edge[] {
  const edges: Edge[] = [];
  // Connect layers conceptually
  const connections = [
    ["dl-lgsp", "ud-qlvb"],
    ["dl-lgsp", "ud-his"],
    ["dl-dancu", "dl-lgsp"],
    ["dl-datdai", "dl-lgsp"],
    ["ht-idc", "dl-dancu"],
    ["ht-wan", "ht-idc"],
    ["ud-qlvb", "kt-web"],
    ["ud-qlvb", "kt-dvctt"],
    ["dl-lgsp", "kt-dvctt"],
  ];

  connections.forEach(([source, target], i) => {
    edges.push({
      id: `e-${i}`,
      source,
      target,
      animated: true,
      style: { stroke: "#1677ff", strokeWidth: 1.5, opacity: 0.6 },
      markerEnd: { type: MarkerType.ArrowClosed, color: "#1677ff" },
    });
  });

  return edges;
}

export default function MucTieuPage() {
  const nodes = buildNodes();
  const edges = buildEdges();

  return (
    <div>
      <div className="page-header mb-6">
        <h1 className="text-2xl font-bold">Kiến trúc Số Mục tiêu</h1>
        <p className="text-blue-200 mt-1">
          Sơ đồ tổng thể kiến trúc số mục tiêu theo 4 lớp — giai đoạn 2026–2028
        </p>
      </div>

      {/* Legend */}
      <div className="flex gap-3 mb-4 flex-wrap">
        {([1, 2, 3, 4] as const).map((lop) => {
          const cfg = LOP_CONFIG[lop];
          return (
            <Tag key={lop} style={{ backgroundColor: cfg.bgColor, borderColor: cfg.borderColor, color: cfg.color }}>
              {cfg.icon} {cfg.shortLabel}
            </Tag>
          );
        })}
        <Tag style={{ backgroundColor: "#f5f5f5", borderColor: "#d9d9d9", color: "#8c8c8c" }}>
          📐 Kế hoạch (chưa triển khai)
        </Tag>
      </div>

      <Card className="shadow-sm" bodyStyle={{ padding: 0 }}>
        <div style={{ height: "720px", width: "100%" }}>
          <ReactFlow
            nodes={nodes}
            edges={edges}
            nodeTypes={nodeTypes}
            fitView
            fitViewOptions={{ padding: 0.1 }}
            minZoom={0.4}
            maxZoom={1.5}
            nodesDraggable={false}
            nodesConnectable={false}
            elementsSelectable={true}
          >
            <Background color="#e8e8e8" gap={20} />
            <Controls />
          </ReactFlow>
        </div>
      </Card>

      {/* Chú thích */}
      <div className="grid grid-cols-4 gap-4 mt-6">
        {([4, 3, 2, 1] as const).map((lop) => {
          const cfg = LOP_CONFIG[lop];
          return (
            <Card
              key={lop}
              size="small"
              style={{ borderColor: cfg.borderColor, backgroundColor: cfg.bgColor }}
            >
              <div className="flex items-center gap-2 mb-2">
                <span className="text-lg">{cfg.icon}</span>
                <span className="font-bold text-sm" style={{ color: cfg.color }}>
                  Lớp {lop}
                </span>
              </div>
              <div className="text-xs text-gray-600">{cfg.label.split("—")[1]?.trim()}</div>
            </Card>
          );
        })}
      </div>
    </div>
  );
}

"use client";
import { useEffect, useState } from "react";
import { Table, Tag, Progress, Select, Card, Badge, Tooltip, Button } from "antd";
import { WarningOutlined, CheckCircleOutlined, ClockCircleOutlined } from "@ant-design/icons";
import type { ColumnsType } from "antd/es/table";
import { NhiemVuData } from "@/types";
import { LOP_CONFIG, TRANG_THAI_CONFIG, UU_TIEN_CONFIG, PHUONG_AN_CONFIG, formatDate, isOverdue, getDaysRemaining } from "@/lib/utils";
import dayjs from "dayjs";

export default function LoTrinhPage() {
  const [data, setData] = useState<NhiemVuData[]>([]);
  const [loading, setLoading] = useState(true);
  const [filterLop, setFilterLop] = useState<string>("");
  const [filterTrangThai, setFilterTrangThai] = useState<string>("");

  useEffect(() => {
    fetch("/api/nhiem-vu")
      .then((r) => r.json())
      .then((d) => { setData(d); setLoading(false); });
  }, []);

  const filtered = data.filter((d) => {
    if (filterLop && d.lop !== parseInt(filterLop)) return false;
    if (filterTrangThai && d.trangThai !== filterTrangThai) return false;
    return true;
  });

  const columns: ColumnsType<NhiemVuData> = [
    {
      title: "Mã",
      dataIndex: "ma",
      width: 80,
      render: (ma) => <span className="font-mono text-xs bg-gray-100 px-2 py-1 rounded">{ma}</span>,
    },
    {
      title: "Nhiệm vụ",
      dataIndex: "ten",
      render: (ten, rec) => (
        <div>
          <div className="font-medium text-gray-800">{ten}</div>
          {rec.moTa && <div className="text-xs text-gray-400 mt-0.5 line-clamp-2">{rec.moTa}</div>}
          {rec.phuongAnXuLy && (
            <div className="text-xs mt-1 text-blue-600">
              {PHUONG_AN_CONFIG[rec.phuongAnXuLy] || rec.phuongAnXuLy}
            </div>
          )}
        </div>
      ),
    },
    {
      title: "Lớp",
      dataIndex: "lop",
      width: 120,
      filters: [1, 2, 3, 4].map((l) => ({ text: LOP_CONFIG[l as 1|2|3|4].shortLabel, value: l })),
      onFilter: (value, record) => record.lop === value,
      render: (lop) => {
        const cfg = LOP_CONFIG[lop as 1|2|3|4];
        return (
          <Tag style={{ color: cfg.color, borderColor: cfg.borderColor, backgroundColor: cfg.bgColor }}>
            {cfg.icon} Lớp {lop}
          </Tag>
        );
      },
    },
    {
      title: "Đơn vị",
      dataIndex: ["donViChuTri", "ten"],
      width: 160,
      render: (_, rec) => rec.donViChuTri?.ten || "—",
    },
    {
      title: "Ưu tiên",
      dataIndex: "uuTien",
      width: 100,
      render: (uuTien) => {
        const cfg = UU_TIEN_CONFIG[uuTien] || { label: uuTien, color: "#8c8c8c" };
        return <Tag color={uuTien === "cao" ? "red" : uuTien === "trung-binh" ? "orange" : "green"}>{cfg.label}</Tag>;
      },
    },
    {
      title: "Thời hạn",
      dataIndex: "thoiHan",
      width: 120,
      render: (thoiHan, rec) => {
        if (!thoiHan) return "—";
        const overdue = isOverdue(thoiHan) && rec.trangThai !== "hoan-thanh";
        const days = getDaysRemaining(thoiHan);
        return (
          <Tooltip title={days !== null ? (overdue ? `Trễ ${Math.abs(days)} ngày` : `Còn ${days} ngày`) : ""}>
            <span className={overdue ? "text-red-500 font-semibold" : days !== null && days <= 30 ? "text-orange-500" : "text-gray-600"}>
              {overdue && <WarningOutlined className="mr-1" />}
              {formatDate(thoiHan)}
            </span>
          </Tooltip>
        );
      },
    },
    {
      title: "Tiến độ",
      dataIndex: "tienDo",
      width: 160,
      render: (tienDo, rec) => (
        <div>
          <Progress
            percent={tienDo}
            size="small"
            status={rec.trangThai === "tre-han" ? "exception" : rec.trangThai === "hoan-thanh" ? "success" : "active"}
            strokeColor={
              rec.trangThai === "hoan-thanh" ? "#52c41a" :
              rec.trangThai === "tre-han" ? "#ff4d4f" :
              tienDo > 50 ? "#1677ff" : "#faad14"
            }
          />
          <div className="text-xs text-gray-400 mt-0.5">
            {TRANG_THAI_CONFIG[rec.trangThai]?.label || rec.trangThai}
          </div>
        </div>
      ),
    },
  ];

  const tongHT = data.filter(d => d.trangThai === 'hoan-thanh').length;
  const tongDT = data.filter(d => d.trangThai === 'dang-thuc-hien').length;
  const tongTH = data.filter(d => d.trangThai === 'tre-han' || (d.thoiHan && isOverdue(d.thoiHan) && d.trangThai !== 'hoan-thanh')).length;

  return (
    <div>
      <div className="page-header mb-6">
        <h1 className="text-2xl font-bold">Lộ trình Nhiệm vụ Chuyển đổi Kiến trúc</h1>
        <p className="text-blue-200 mt-1">
          Theo dõi tiến độ các nhiệm vụ chuyển đổi kiến trúc số theo lộ trình 2026–2028
        </p>
      </div>

      {/* Quick stats */}
      <div className="flex gap-4 mb-4">
        <Badge count={data.length} color="#1677ff" overflowCount={99}>
          <Card size="small" className="px-4 py-2 min-w-[100px] text-center">
            <div className="text-lg font-bold text-gray-800">{data.length}</div>
            <div className="text-xs text-gray-400">Tổng nhiệm vụ</div>
          </Card>
        </Badge>
        <Card size="small" className="px-4 py-2 min-w-[100px] text-center bg-green-50 border-green-200">
          <div className="text-lg font-bold text-green-600"><CheckCircleOutlined /> {tongHT}</div>
          <div className="text-xs text-gray-400">Hoàn thành</div>
        </Card>
        <Card size="small" className="px-4 py-2 min-w-[100px] text-center bg-blue-50 border-blue-200">
          <div className="text-lg font-bold text-blue-600"><ClockCircleOutlined /> {tongDT}</div>
          <div className="text-xs text-gray-400">Đang thực hiện</div>
        </Card>
        <Card size="small" className="px-4 py-2 min-w-[100px] text-center bg-red-50 border-red-200">
          <div className="text-lg font-bold text-red-600"><WarningOutlined /> {tongTH}</div>
          <div className="text-xs text-gray-400">Cảnh báo</div>
        </Card>
      </div>

      {/* Filters */}
      <Card className="mb-4 shadow-sm">
        <div className="flex gap-4 items-center">
          <span className="text-gray-600 font-medium">Lọc:</span>
          <Select
            placeholder="Tất cả lớp"
            allowClear
            style={{ width: 200 }}
            onChange={setFilterLop}
          >
            {[1, 2, 3, 4].map((l) => (
              <Select.Option key={l} value={String(l)}>
                {LOP_CONFIG[l as 1|2|3|4].icon} {LOP_CONFIG[l as 1|2|3|4].shortLabel}
              </Select.Option>
            ))}
          </Select>
          <Select
            placeholder="Tất cả trạng thái"
            allowClear
            style={{ width: 200 }}
            onChange={setFilterTrangThai}
          >
            {Object.entries(TRANG_THAI_CONFIG).map(([k, v]) => (
              <Select.Option key={k} value={k}>{v.label}</Select.Option>
            ))}
          </Select>
          <span className="text-gray-400 text-sm ml-auto">
            Hiển thị {filtered.length}/{data.length} nhiệm vụ
          </span>
        </div>
      </Card>

      <Card className="shadow-sm">
        <Table
          columns={columns}
          dataSource={filtered}
          rowKey="id"
          loading={loading}
          pagination={{ pageSize: 20 }}
          rowClassName={(record) => {
            if (record.trangThai === "hoan-thanh") return "bg-green-50";
            if (isOverdue(record.thoiHan) && record.trangThai !== "hoan-thanh") return "bg-red-50";
            return "";
          }}
          size="middle"
        />
      </Card>
    </div>
  );
}

"use client";
