"use client";
import { useState, useEffect } from "react";
import { Table, Button, Modal, Form, Input, Select, DatePicker, Tag, message, Popconfirm, Card, Progress, Slider } from "antd";
import { PlusOutlined, EditOutlined, DeleteOutlined, WarningOutlined } from "@ant-design/icons";
import type { ColumnsType } from "antd/es/table";
import { NhiemVuData, DonViData } from "@/types";
import { LOP_CONFIG, TRANG_THAI_CONFIG, UU_TIEN_CONFIG, PHUONG_AN_CONFIG, formatDate, isOverdue } from "@/lib/utils";
import dayjs from "dayjs";

const { TextArea } = Input;

export default function AdminNhiemVuPage() {
  const [data, setData] = useState<NhiemVuData[]>([]);
  const [donVis, setDonVis] = useState<DonViData[]>([]);
  const [loading, setLoading] = useState(true);
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<NhiemVuData | null>(null);
  const [form] = Form.useForm();
  const [saving, setSaving] = useState(false);

  const load = () => {
    setLoading(true);
    Promise.all([
      fetch("/api/nhiem-vu").then(r => r.json()),
      fetch("/api/don-vi").then(r => r.json()),
    ]).then(([nv, dv]) => { setData(nv); setDonVis(dv); setLoading(false); });
  };

  useEffect(() => { load(); }, []);

  const openEdit = (record: NhiemVuData) => {
    setEditing(record);
    form.setFieldsValue({ ...record, thoiHan: record.thoiHan ? dayjs(record.thoiHan) : null });
    setModalOpen(true);
  };

  const openCreate = () => {
    setEditing(null);
    form.resetFields();
    form.setFieldsValue({ trangThai: "chua-bat-dau", uuTien: "trung-binh", tienDo: 0, lop: 2 });
    setModalOpen(true);
  };

  const handleSave = async () => {
    try {
      const values = await form.validateFields();
      setSaving(true);
      const payload = { ...values, thoiHan: values.thoiHan ? values.thoiHan.toISOString() : null };
      const url = editing ? `/api/nhiem-vu/${editing.id}` : "/api/nhiem-vu";
      const method = editing ? "PUT" : "POST";
      const res = await fetch(url, { method, headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) });
      if (res.ok) { message.success(editing ? "Đã cập nhật!" : "Đã thêm!"); setModalOpen(false); load(); }
      else message.error("Lỗi khi lưu!");
    } catch {}
    setSaving(false);
  };

  const handleDelete = async (id: string) => {
    const res = await fetch(`/api/nhiem-vu/${id}`, { method: "DELETE" });
    if (res.ok) { message.success("Đã xóa!"); load(); }
  };

  const columns: ColumnsType<NhiemVuData> = [
    { title: "Mã", dataIndex: "ma", width: 80, render: ma => <span className="font-mono text-xs bg-gray-100 px-2 py-1 rounded">{ma}</span> },
    { title: "Nhiệm vụ", dataIndex: "ten", render: (ten, rec) => (
      <div>
        <div className="font-medium text-gray-800">{ten}</div>
        {rec.phuongAnXuLy && <div className="text-xs text-blue-500">{PHUONG_AN_CONFIG[rec.phuongAnXuLy]}</div>}
      </div>
    )},
    { title: "Lớp", dataIndex: "lop", width: 100, render: lop => {
      const cfg = LOP_CONFIG[lop as 1|2|3|4];
      return <Tag style={{ color: cfg.color, backgroundColor: cfg.bgColor, borderColor: cfg.borderColor }}>{cfg.icon} L{lop}</Tag>;
    }},
    { title: "Ưu tiên", dataIndex: "uuTien", width: 90, render: uuTien => (
      <Tag color={uuTien === "cao" ? "red" : uuTien === "trung-binh" ? "orange" : "green"}>
        {UU_TIEN_CONFIG[uuTien]?.label || uuTien}
      </Tag>
    )},
    { title: "Thời hạn", dataIndex: "thoiHan", width: 110, render: (d, rec) => {
      const overdue = isOverdue(d) && rec.trangThai !== "hoan-thanh";
      return <span className={overdue ? "text-red-500 font-semibold" : "text-gray-600"}>
        {overdue && <WarningOutlined className="mr-1" />}{formatDate(d)}
      </span>;
    }},
    { title: "Tiến độ", dataIndex: "tienDo", width: 150, render: (p, rec) => (
      <div>
        <Progress percent={p} size="small" status={rec.trangThai === "hoan-thanh" ? "success" : isOverdue(rec.thoiHan) && rec.trangThai !== "hoan-thanh" ? "exception" : "active"} />
        <div className="text-xs text-gray-400">{TRANG_THAI_CONFIG[rec.trangThai]?.label}</div>
      </div>
    )},
    { title: "Thao tác", width: 90, render: (_, rec) => (
      <div className="flex gap-1">
        <Button icon={<EditOutlined />} size="small" onClick={() => openEdit(rec)} />
        <Popconfirm title="Xóa nhiệm vụ này?" onConfirm={() => handleDelete(rec.id)} okText="Xóa" cancelText="Hủy" okButtonProps={{ danger: true }}>
          <Button icon={<DeleteOutlined />} size="small" danger />
        </Popconfirm>
      </div>
    )},
  ];

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-xl font-bold text-gray-800">Nhiệm vụ & Lộ trình</h1>
          <p className="text-gray-400 text-sm">Quản lý các nhiệm vụ chuyển đổi kiến trúc số (tương ứng bảng HOANTHIEN_NV trong Mẫu 03)</p>
        </div>
        <Button type="primary" icon={<PlusOutlined />} onClick={openCreate} style={{ backgroundColor: "#003087" }}>
          Thêm nhiệm vụ
        </Button>
      </div>
      <Card className="shadow-sm">
        <Table columns={columns} dataSource={data} rowKey="id" loading={loading} size="middle" pagination={{ pageSize: 20 }}
          rowClassName={r => isOverdue(r.thoiHan) && r.trangThai !== "hoan-thanh" ? "bg-red-50" : r.trangThai === "hoan-thanh" ? "bg-green-50" : ""} />
      </Card>

      <Modal title={editing ? "Sửa nhiệm vụ" : "Thêm nhiệm vụ mới"} open={modalOpen} onOk={handleSave} onCancel={() => setModalOpen(false)} confirmLoading={saving} okText={editing ? "Cập nhật" : "Thêm mới"} width={720}>
        <Form form={form} layout="vertical" className="mt-4">
          <div className="grid grid-cols-3 gap-4">
            <Form.Item label="Mã" name="ma" rules={[{ required: true }]}><Input placeholder="NV-01" /></Form.Item>
            <Form.Item label="Lớp" name="lop" rules={[{ required: true }]}>
              <Select>{[1,2,3,4].map(l => <Select.Option key={l} value={l}>{LOP_CONFIG[l as 1|2|3|4].icon} Lớp {l}</Select.Option>)}</Select>
            </Form.Item>
            <Form.Item label="Ưu tiên" name="uuTien"><Select><Select.Option value="cao">🔴 Cao</Select.Option><Select.Option value="trung-binh">🟡 Trung bình</Select.Option><Select.Option value="thap">🟢 Thấp</Select.Option></Select></Form.Item>
          </div>
          <Form.Item label="Tên nhiệm vụ" name="ten" rules={[{ required: true }]}><Input /></Form.Item>
          <Form.Item label="Mô tả" name="moTa"><TextArea rows={3} /></Form.Item>
          <div className="grid grid-cols-2 gap-4">
            <Form.Item label="Đơn vị chủ trì" name="donViChuTriId">
              <Select allowClear placeholder="Chọn đơn vị">
                {donVis.map(dv => <Select.Option key={dv.id} value={dv.id}>{dv.ten}</Select.Option>)}
              </Select>
            </Form.Item>
            <Form.Item label="Thời hạn hoàn thành" name="thoiHan"><DatePicker style={{ width: "100%" }} format="DD/MM/YYYY" /></Form.Item>
            <Form.Item label="Giai đoạn" name="giaiDoan"><Input placeholder="2026-2027" /></Form.Item>
            <Form.Item label="Trạng thái" name="trangThai">
              <Select>
                <Select.Option value="chua-bat-dau">Chưa bắt đầu</Select.Option>
                <Select.Option value="dang-thuc-hien">Đang thực hiện</Select.Option>
                <Select.Option value="hoan-thanh">Hoàn thành</Select.Option>
                <Select.Option value="tre-han">Trễ hạn</Select.Option>
              </Select>
            </Form.Item>
          </div>
          <Form.Item label="Phương án xử lý" name="phuongAnXuLy">
            <Select allowClear placeholder="Chọn phương án">
              {Object.entries(PHUONG_AN_CONFIG).map(([k, v]) => <Select.Option key={k} value={k}>{v}</Select.Option>)}
            </Select>
          </Form.Item>
          <Form.Item label="KPI / Tiêu chí kiểm chứng" name="kpi"><TextArea rows={2} /></Form.Item>
          <Form.Item label={`Tiến độ thực hiện`} name="tienDo">
            <Slider marks={{ 0: "0%", 25: "25%", 50: "50%", 75: "75%", 100: "100%" }} />
          </Form.Item>
          <Form.Item label="Ghi chú" name="ghiChu"><TextArea rows={2} /></Form.Item>
        </Form>
      </Modal>
    </div>
  );
}

"use client";
import { useState } from "react";
import { Card, Upload, Button, Table, Alert, Tag, message, Steps } from "antd";
import { UploadOutlined, CheckCircleOutlined, InboxOutlined } from "@ant-design/icons";
import * as XLSX from "xlsx";

const { Dragger } = Upload;

interface PreviewRow {
  ma: string;
  ten: string;
  lop: number;
  trangThai: string;
  moTa?: string;
  chuQuan?: string;
}

export default function AdminImportPage() {
  const [preview, setPreview] = useState<PreviewRow[]>([]);
  const [importing, setImporting] = useState(false);
  const [step, setStep] = useState(0);
  const [importResult, setImportResult] = useState<{ success: number; error: number } | null>(null);

  const handleFile = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: "array" });

        // Thử đọc sheet DM_DOITUONG (Bảng 1 trong Mẫu 03)
        const sheetName = workbook.SheetNames.find(n => 
          n.includes("DM_DOITUONG") || n.includes("Danh muc") || n === workbook.SheetNames[0]
        ) || workbook.SheetNames[0];

        const sheet = workbook.Sheets[sheetName];
        const rows = XLSX.utils.sheet_to_json<Record<string, string>>(sheet, { header: 1 });

        // Parse rows (bỏ qua header)
        const parsed: PreviewRow[] = [];
        for (let i = 1; i < rows.length; i++) {
          const row = rows[i] as unknown as string[];
          if (!row || !row[1]) continue; // Bỏ qua dòng trống
          parsed.push({
            ma: String(row[0] || `HT-${i.toString().padStart(2, "0")}`),
            ten: String(row[1] || ""),
            lop: parseInt(String(row[2])) || 1,
            trangThai: String(row[3] || "dang-van-hanh"),
            moTa: String(row[4] || ""),
            chuQuan: String(row[5] || ""),
          });
        }

        setPreview(parsed);
        setStep(1);
        message.success(`Đọc được ${parsed.length} dòng từ sheet "${sheetName}"`);
      } catch (err) {
        message.error("Lỗi đọc file XLSX. Vui lòng kiểm tra định dạng.");
      }
    };
    reader.readAsArrayBuffer(file);
    return false; // Ngăn auto upload
  };

  const handleImport = async () => {
    setImporting(true);
    let success = 0, error = 0;

    for (const row of preview) {
      try {
        const res = await fetch("/api/he-thong", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(row),
        });
        if (res.ok) success++;
        else error++;
      } catch {
        error++;
      }
    }

    setImportResult({ success, error });
    setStep(2);
    setImporting(false);
    message.success(`Import hoàn tất: ${success} thành công, ${error} lỗi`);
  };

  const previewColumns = [
    { title: "Mã", dataIndex: "ma", width: 90, render: (v: string) => <span className="font-mono text-xs">{v}</span> },
    { title: "Tên hệ thống", dataIndex: "ten" },
    { title: "Lớp", dataIndex: "lop", width: 60, render: (l: number) => <Tag color="blue">L{l}</Tag> },
    { title: "Trạng thái", dataIndex: "trangThai", width: 130 },
    { title: "Chủ quản", dataIndex: "chuQuan", width: 120 },
  ];

  return (
    <div>
      <div className="mb-6">
        <h1 className="text-xl font-bold text-gray-800">Import XLSX Mẫu 03</h1>
        <p className="text-gray-400 text-sm">
          Import dữ liệu từ file XLSX chuẩn Mẫu 03 của Bộ KHCN (bảng DM_DOITUONG)
        </p>
      </div>

      <Steps
        current={step}
        className="mb-8"
        items={[
          { title: "Tải file XLSX", description: "Chọn file Mẫu 03" },
          { title: "Kiểm tra dữ liệu", description: "Xem trước và xác nhận" },
          { title: "Hoàn tất", description: "Import thành công" },
        ]}
      />

      {step === 0 && (
        <Card className="shadow-sm">
          <Alert
            message="Định dạng file yêu cầu"
            description={
              <div className="text-sm">
                <p>File XLSX phải có sheet <strong>DM_DOITUONG</strong> với các cột theo thứ tự:</p>
                <p className="font-mono text-xs mt-2 bg-gray-50 p-2 rounded">
                  [A] Mã | [B] Tên hệ thống | [C] Lớp (1-4) | [D] Trạng thái | [E] Mô tả | [F] Chủ quản
                </p>
              </div>
            }
            type="info"
            className="mb-4"
          />
          <Dragger
            accept=".xlsx,.xls"
            beforeUpload={handleFile}
            showUploadList={false}
            className="py-8"
          >
            <p className="text-4xl mb-4">📊</p>
            <p className="text-lg font-medium text-gray-700">Kéo thả file XLSX vào đây</p>
            <p className="text-gray-400 mt-1">hoặc click để chọn file</p>
            <p className="text-xs text-gray-300 mt-2">Hỗ trợ: .xlsx, .xls — Mẫu 03 theo chuẩn Bộ KHCN</p>
          </Dragger>
        </Card>
      )}

      {step === 1 && (
        <div className="space-y-4">
          <Card className="shadow-sm">
            <div className="flex items-center justify-between mb-4">
              <div>
                <span className="font-bold text-gray-700">Xem trước dữ liệu</span>
                <span className="ml-2 text-gray-400 text-sm">({preview.length} hệ thống sẽ được import)</span>
              </div>
              <div className="flex gap-3">
                <Button onClick={() => { setStep(0); setPreview([]); }}>← Tải lại file</Button>
                <Button
                  type="primary"
                  icon={<CheckCircleOutlined />}
                  loading={importing}
                  onClick={handleImport}
                  style={{ backgroundColor: "#003087" }}
                >
                  Xác nhận Import {preview.length} hệ thống
                </Button>
              </div>
            </div>
            <Table
              columns={previewColumns}
              dataSource={preview}
              rowKey="ma"
              size="small"
              pagination={{ pageSize: 20 }}
              scroll={{ y: 400 }}
            />
          </Card>
        </div>
      )}

      {step === 2 && importResult && (
        <Card className="shadow-sm text-center py-12">
          <div className="text-6xl mb-4">✅</div>
          <h2 className="text-2xl font-bold text-green-600 mb-2">Import hoàn tất!</h2>
          <div className="flex justify-center gap-8 mt-4">
            <div className="text-center">
              <div className="text-3xl font-bold text-green-600">{importResult.success}</div>
              <div className="text-gray-400 text-sm">Thành công</div>
            </div>
            {importResult.error > 0 && (
              <div className="text-center">
                <div className="text-3xl font-bold text-red-500">{importResult.error}</div>
                <div className="text-gray-400 text-sm">Lỗi</div>
              </div>
            )}
          </div>
          <div className="flex justify-center gap-3 mt-8">
            <Button onClick={() => { setStep(0); setPreview([]); setImportResult(null); }}>Import file khác</Button>
            <Button type="primary" href="/admin/he-thong" style={{ backgroundColor: "#003087" }}>
              Xem danh sách hệ thống →
            </Button>
          </div>
        </Card>
      )}
    </div>
  );
}

"use client";
import { useState } from "react";
import { Card, Form, Input, Button, message, Divider } from "antd";
import { LockOutlined, MailOutlined, ApartmentOutlined } from "@ant-design/icons";
import { signIn } from "next-auth/react";
import { useRouter } from "next/navigation";
import { SessionProvider } from "next-auth/react";

function LoginForm() {
  const [loading, setLoading] = useState(false);
  const router = useRouter();

  const onFinish = async (values: { email: string; password: string }) => {
    setLoading(true);
    const result = await signIn("credentials", {
      email: values.email,
      password: values.password,
      redirect: false,
    });
    setLoading(false);
    if (result?.ok) {
      message.success("Đăng nhập thành công!");
      router.push("/admin/khung");
    } else {
      message.error("Email hoặc mật khẩu không đúng!");
    }
  };

  return (
    <div className="min-h-screen hero-gradient flex items-center justify-center p-4">
      <Card
        className="w-full max-w-md shadow-2xl border-0"
        style={{ borderRadius: 16 }}
      >
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-blue-800 rounded-2xl flex items-center justify-center mx-auto mb-4">
            <ApartmentOutlined className="text-white text-3xl" />
          </div>
          <h1 className="text-2xl font-bold text-gray-800">Đăng nhập</h1>
          <p className="text-gray-400 text-sm mt-1">
            Hệ thống Quản lý Khung Kiến trúc Số<br />
            <span className="font-medium text-blue-700">Tỉnh Vĩnh Long</span>
          </p>
        </div>

        <Form layout="vertical" onFinish={onFinish} size="large">
          <Form.Item
            name="email"
            rules={[{ required: true, message: "Vui lòng nhập email!" }, { type: "email", message: "Email không hợp lệ!" }]}
          >
            <Input
              prefix={<MailOutlined className="text-gray-300" />}
              placeholder="Email"
              autoComplete="email"
            />
          </Form.Item>
          <Form.Item
            name="password"
            rules={[{ required: true, message: "Vui lòng nhập mật khẩu!" }]}
          >
            <Input.Password
              prefix={<LockOutlined className="text-gray-300" />}
              placeholder="Mật khẩu"
              autoComplete="current-password"
            />
          </Form.Item>
          <Button
            type="primary"
            htmlType="submit"
            loading={loading}
            block
            size="large"
            style={{ backgroundColor: "#003087", height: 48, borderRadius: 8, fontSize: 16 }}
          >
            Đăng nhập
          </Button>
        </Form>

        <Divider className="my-4" />
        <div className="text-center text-xs text-gray-300">
          <div className="font-medium text-gray-400 mb-1">Tài khoản demo:</div>
          <div>admin@vinhlong.gov.vn / admin123</div>
          <div>editor@vinhlong.gov.vn / editor123</div>
        </div>
      </Card>
    </div>
  );
}

export default function LoginPage() {
  return (
    <SessionProvider>
      <LoginForm />
    </SessionProvider>
  );
}

