                return; // Đã có dữ liệu
            }

            var donVi = new DonVi { Id = "DV01", Ten = "Sở Thông tin và Truyền thông", Loai = "so" };
            context.DonVis.Add(donVi);

            var heThongSos = new HeThongSo[]
            {
                new HeThongSo { Id = "HT01", Ma = "HT-01", Ten = "Trục tích hợp chia sẻ dữ liệu LGSP", Loai = "du-lieu", Lop = 2, ChuQuan = "Sở TT&TT", TrangThai = "dang-van-hanh", DonViId = "DV01" },
                new HeThongSo { Id = "HT02", Ma = "HT-02", Ten = "Hệ thống Quản lý Văn bản và Điều hành", Loai = "ung-dung", Lop = 3, ChuQuan = "Sở TT&TT", TrangThai = "dang-van-hanh", DonViId = "DV01" },
                new HeThongSo { Id = "HT03", Ma = "HT-03", Ten = "Cổng Dịch vụ công trực tuyến", Loai = "kenh-tuong-tac", Lop = 4, ChuQuan = "Sở TT&TT", TrangThai = "dang-van-hanh", DonViId = "DV01" },
                new HeThongSo { Id = "HT04", Ma = "HT-04", Ten = "Hệ thống Mạng diện rộng (WAN) tỉnh", Loai = "ha-tang", Lop = 1, ChuQuan = "Sở TT&TT", TrangThai = "dang-van-hanh", DonViId = "DV01" }
